                                <option key={shop} value={shop}>{shop}</option>
                            ))}
                        </select>
                    </div>
                    <div className="flex-1 w-full">
                        <label className={`block text-xs font-medium mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Status</label>
