import { availableProductUnits, mockShops } from '../data';

interface AddProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Omit<ProductDefinition, 'id' | 'sn' | 'createdAt' | 'updatedAt' | 'updatedBy'>) => void;
  theme: Theme;
}

const manufacturers = ['Unknown Manufacturer', 'Samsung', 'LG', 'Sony', 'Apple', 'Coca Cola', 'Pepsi'];
const categories = ['Adhesives', 'Cosmetics', 'Electronics', 'Chemicals', 'Household', 'Industrial', 'Beverages'];
const warehouses = [
    { id: 101, name: 'Main Warehouse - Kampala' },
    { id: 102, name: 'Distribution Center - Jinja' },
    { id: 103, name: 'Storage Unit B' }
];

const Toggle = ({ label, description, checked, onChange, theme }: { label: string, description?: string, checked: boolean, onChange: (val: boolean) => void, theme: Theme }) => (
    <div className="flex items-center justify-between py-2">
        <div>
            <div className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{label}</div>
            {description && <div className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{description}</div>}
        </div>
        <button
            type="button"
            onClick={() => onChange(!checked)}
            className={`ml-4 relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-yellow-500' : (theme === 'dark' ? 'bg-slate-600' : 'bg-slate-200')}`}
        >
            <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </button>
    </div>
);

const AddProductModal: React.FC<AddProductModalProps> = ({ isOpen, onClose, onSave, theme }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [formData, setFormData] = useState({
        manufacturer: '',
        name: '',
        category: '',
        status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE',
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        remarks: '',
        country: '',
        hasBatchNumber: false,
        hasExpiryDate: false,
        locationType: 'Shop' as 'Shop' | 'Warehouse',
        locationId: '',
        imageUrl: '',
    });

    // Multi-select units state
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isUnitDropdownOpen]);

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
            // Reset form
            setFormData({
                manufacturer: '',
                name: '',
                category: '',
                status: 'ACTIVE',
                baseUnit: '',
                baseQuantity: '',
                containerQuantity: '',
                containerUnit: '',
                remarks: '',
                country: '',
                hasBatchNumber: false,
                hasExpiryDate: false,
                locationType: 'Shop',
                locationId: '',
                imageUrl: '',
            });
            setSelectedUnits([]);
            setUnitDetails({});
        }, 300);
    };

    const handleSave = () => {
        if (!formData.name || !formData.manufacturer || !formData.category || !formData.baseUnit) {
            alert("Please fill in required fields (Manufacturer, Name, Category, Base Unit).");
            return;
        }

        let finalBarcode = '0000';

        // Validation for unit barcodes
        if (selectedUnits.length > 0) {
            const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
            if (!unitWithBarcode) {
                alert("When product units are selected, at least one unit must have a barcode.");
                return;
            }
            // Use the first valid barcode found as the main barcode if needed, or simply proceed
            finalBarcode = unitDetails[unitWithBarcode].barcode;
        }

        // Convert unit details map to array for saving
        const definedUnits = selectedUnits.map(u => unitDetails[u]);

        onSave({
            name: formData.name,
            manufacturer: formData.manufacturer,
            category: formData.category,
            status: formData.status,
            barcode: finalBarcode, // Main barcode derived from units or default
            baseUnit: formData.baseUnit,
            baseQuantity: parseFloat(formData.baseQuantity) || 0,
            containerQuantity: parseFloat(formData.containerQuantity) || 0,
            containerUnit: formData.containerUnit,
            saleUnits: selectedUnits.join(', '), // Store as comma separated string for display compat
            definedUnits: definedUnits,
            remarks: formData.remarks,
            country: formData.country || 'Unknown', 
            hasBatchNumber: formData.hasBatchNumber,
            hasExpiryDate: formData.hasExpiryDate,
            createdBy: 'Current User',
            imageUrl: formData.imageUrl,
        });
        handleClose();
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    if (!isOpen && !isClosing) return null;

    const commonInputClasses = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClasses = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className={`fixed inset-0 bg-black z-[80] flex justify-center items-center p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100 bg-opacity-50' : 'opacity-0'}`}>
            <div className={`${theme === 'dark' ? 'bg-slate-900' : 'bg-white'} rounded-lg shadow-xl w-full max-w-3xl flex flex-col transition-all duration-300 ease-in-out ${isOpen && !isClosing ? 'scale-100 opacity-100' : 'scale-95 opacity-0'} max-h-[90vh]`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>Product</h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* Image Uploader */}
                    <div className="flex flex-col items-center justify-center p-4 border-2 border-dashed rounded-lg border-slate-300 dark:border-slate-700 hover:border-yellow-500 transition-colors">
                        {formData.imageUrl ? (
                            <div className="relative group w-40 h-40">
                                <img src={formData.imageUrl} alt="Product preview" className="w-full h-full object-cover rounded-md" />
                                <button 
                                    onClick={() => setFormData(prev => ({ ...prev, imageUrl: '' }))}
                                    className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600 transition-colors"
                                >
                                    <Icon name="x-mark" className="h-4 w-4" />
                                </button>
                            </div>
                        ) : (
                            <label className="cursor-pointer flex flex-col items-center justify-center space-y-2">
                                <div className="p-3 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                                    <Icon name="camera" className="h-8 w-8" />
                                </div>
                                <span className="text-sm font-medium text-slate-600 dark:text-slate-400">Upload Product Image</span>
                                <input type="file" className="hidden" accept="image/*" onChange={handleImageChange} />
                            </label>
                        )}
                    </div>

                    {/* General Info */}
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className={labelClasses}>Manufacturer<span className="text-red-500">*</span></label>
                            <select name="manufacturer" value={formData.manufacturer} onChange={handleChange} className={commonInputClasses}>
                                <option value="">Select Manufacturer</option>
                                {manufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className={labelClasses}>Name<span className="text-red-500">*</span></label>
                            <input type="text" name="name" value={formData.name} onChange={handleChange} className={commonInputClasses} placeholder="Product Name" />
                        </div>

                        {/* Type and Location Row */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Location Type</label>
                                <select 
                                    name="locationType" 
                                    value={formData.locationType} 
                                    onChange={(e) => setFormData(prev => ({ ...prev, locationType: e.target.value as any, locationId: '' }))} 
                                    className={commonInputClasses}
                                >
                                    <option value="Shop">Shop</option>
                                    <option value="Warehouse">Warehouse</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>{formData.locationType}</label>
                                <select name="locationId" value={formData.locationId} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select {formData.locationType}</option>
                                    {formData.locationType === 'Shop' 
                                        ? mockShops.map(s => <option key={s.id} value={s.id}>{s.name}</option>)
                                        : warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)
                                    }
                                </select>
                            </div>
                        </div>

                        {/* Category and Status Row */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Category<span className="text-red-500">*</span></label>
                                <select name="category" value={formData.category} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select Category</option>
                                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Production status<span className="text-red-500">*</span></label>
                                <select name="status" value={formData.status} onChange={handleChange} className={commonInputClasses}>
                                    <option value="ACTIVE">Active</option>
                                    <option value="INACTIVE">Inactive</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Metrics */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Metrics</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Base Unit<span className="text-red-500">*</span></label>
                                <select name="baseUnit" value={formData.baseUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Base unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Base quantity<span className="text-red-500">*</span></label>
                                <input type="number" name="baseQuantity" value={formData.baseQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 20 (grams/ml)" />
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Container quantity</label>
                                <input type="number" name="containerQuantity" value={formData.containerQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 12 (items in container)" />
                            </div>
                            <div>
                                <label className={labelClasses}>Container Unit</label>
                                <select name="containerUnit" value={formData.containerUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Container Unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>

                        {/* Multi-select Product Units */}
                        <div className="mb-4">
                            <label className={labelClasses}>Product units<span className="text-red-500">*</span></label>
                            <div className="relative" ref={unitDropdownRef}>
                                <div 
                                    className={`w-full rounded-md border shadow-sm px-3 py-2 text-sm min-h-[38px] flex flex-wrap gap-2 items-center cursor-pointer focus-within:ring-1 focus-within:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600' : 'bg-white border-slate-300'}`}
                                    onClick={() => setIsUnitDropdownOpen(!isUnitDropdownOpen)}
                                >
                                    {selectedUnits.length === 0 && <span className="text-gray-400">Select units</span>}
                                    {selectedUnits.map(unit => (
                                        <span key={unit} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-yellow-100 text-yellow-800 border border-yellow-200">
                                            {unit}
                                            <button 
                                                type="button"
                                                onClick={(e) => { e.stopPropagation(); handleUnitToggle(unit); }}
                                                className="ml-1 text-yellow-900 hover:text-yellow-600 focus:outline-none"
                                            >
                                                <Icon name="x-mark" className="h-3 w-3" />
                                            </button>
                                        </span>
                                    ))}
                                    <div className="ml-auto"><Icon name="chevron-down" className="h-4 w-4 text-gray-400" /></div>
                                </div>
                                {isUnitDropdownOpen && (
                                    <div className={`absolute z-10 mt-1 w-full rounded-md shadow-lg max-h-48 overflow-auto border ${theme === 'dark' ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-300'}`}>
                                        {availableProductUnits.map(unit => (
                                            <div 
                                                key={unit} 
                                                className={`px-3 py-2 cursor-pointer text-sm flex items-center justify-between ${theme === 'dark' ? 'hover:bg-slate-700 text-slate-200' : 'hover:bg-slate-100 text-slate-800'} ${selectedUnits.includes(unit) ? 'bg-yellow-500/10' : ''}`}
                                                onClick={() => handleUnitToggle(unit)}
                                            >
                                                {unit}
                                                {selectedUnits.includes(unit) && <Icon name="check-circle" className="h-4 w-4 text-yellow-500" />}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Dynamic Unit Inputs */}
                        {selectedUnits.length > 0 && (
                            <div className="space-y-3 mb-4">
                                <div className="grid grid-cols-3 gap-4">
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Unit name*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Quantity*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Barcode</label>
                                </div>
                                {selectedUnits.map(unit => (
                                    <div key={unit} className="grid grid-cols-3 gap-4">
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.unitName || unit} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'unitName', e.target.value)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="number" 
                                            value={unitDetails[unit]?.quantity || 1} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'quantity', parseFloat(e.target.value) || 0)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.barcode || ''} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'barcode', e.target.value)}
                                            className={commonInputClasses} 
                                            placeholder="Barcode"
                                        />
                                    </div>
                                ))}
                            </div>
                        )}

                    </div>

                    {/* Tracking Settings & Remarks */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Tracking</h3>
                        <div className="space-y-4 mb-4">
                             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <Toggle 
                                    label="Batch Number Tracking" 
                                    description="Enable to track batch #."
                                    checked={formData.hasBatchNumber} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasBatchNumber: val}))} 
                                    theme={theme} 
                                />
                                <Toggle 
                                    label="Expiry Date Tracking" 
                                    description="Enable to track expiry."
                                    checked={formData.hasExpiryDate} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasExpiryDate: val}))} 
                                    theme={theme} 
                                />
                            </div>
                        </div>
                        <div>
                            <label className={labelClasses}>Remarks</label>
                            <textarea name="remarks" value={formData.remarks} onChange={handleChange} className={commonInputClasses} rows={3} placeholder="Product description"></textarea>
                        </div>
                    </div>
                </div>

                <div className={`flex justify-end items-center p-6 border-t rounded-b-lg ${theme === 'dark' ? 'border-slate-700 bg-black/50' : 'border-slate-200 bg-slate-100'}`}>
                    <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm mr-3 ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                        Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                        <Icon name="check-circle" className="h-4 w-4 mr-2" />
                        Save
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AddProductModal;

import React, { useState, useEffect, useRef } from 'react';
import { Theme, ProductDefinition, ProductUnitDefinition } from '../types';
import Icon from './Icon';
import { availableProductUnits } from '../data';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (product: ProductDefinition) => void;
  productToEdit: ProductDefinition | null;
  theme: Theme;
}

const manufacturers = ['Unknown Manufacturer', 'Samsung', 'LG', 'Sony', 'Apple', 'Coca Cola', 'Pepsi'];
const categories = ['Adhesives', 'Cosmetics', 'Electronics', 'Chemicals', 'Household', 'Industrial', 'Beverages'];

const Toggle = ({ label, description, checked, onChange, theme }: { label: string, description?: string, checked: boolean, onChange: (val: boolean) => void, theme: Theme }) => (
    <div className="flex items-center justify-between py-2">
        <div>
            <div className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{label}</div>
            {description && <div className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{description}</div>}
        </div>
        <button
            type="button"
            onClick={() => onChange(!checked)}
            className={`ml-4 relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-yellow-500' : (theme === 'dark' ? 'bg-slate-600' : 'bg-slate-200')}`}
        >
            <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </button>
    </div>
);

const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onUpdate, productToEdit, theme }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [formData, setFormData] = useState({
        manufacturer: '',
        name: '',
        category: '',
        status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE',
        barcode: '',
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        remarks: '',
        hasBatchNumber: false,
        hasExpiryDate: false,
        imageUrl: '',
    });

    // Multi-select units state
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (isOpen && productToEdit) {
            setFormData({
                manufacturer: productToEdit.manufacturer,
                name: productToEdit.name,
                category: productToEdit.category || '',
                status: productToEdit.status,
                barcode: productToEdit.barcode,
                baseUnit: productToEdit.baseUnit || '',
                baseQuantity: productToEdit.baseQuantity?.toString() || '',
                containerQuantity: productToEdit.containerQuantity?.toString() || '',
                containerUnit: productToEdit.containerUnit || '',
                remarks: productToEdit.remarks || '',
                hasBatchNumber: !!productToEdit.hasBatchNumber,
                hasExpiryDate: !!productToEdit.hasExpiryDate,
                imageUrl: productToEdit.imageUrl || '',
            });

            // Populate units
            const unitsList = productToEdit.definedUnits ? productToEdit.definedUnits.map(u => u.unitName) : (productToEdit.saleUnits ? productToEdit.saleUnits.split(',').map(s => s.trim()) : []);
            setSelectedUnits(unitsList);

            const details: Record<string, ProductUnitDefinition> = {};
            if (productToEdit.definedUnits) {
                productToEdit.definedUnits.forEach(u => {
                    details[u.unitName] = u;
                });
            } else {
                // Fallback if only saleUnits string exists
                unitsList.forEach(u => {
                    details[u] = { unitName: u, quantity: 1, barcode: '' };
                });
            }
            setUnitDetails(details);
        }
    }, [isOpen, productToEdit]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isUnitDropdownOpen]);

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
        }, 300);
    };

    const handleSave = () => {
        if (!productToEdit) return;

        if (!formData.name || !formData.manufacturer || !formData.category || !formData.baseUnit) {
            alert("Please fill in required fields (Manufacturer, Name, Category, Base Unit).");
            return;
        }

        let finalBarcode = formData.barcode || '0000';

        // Validation for unit barcodes
        if (selectedUnits.length > 0) {
            const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
            if (!unitWithBarcode) {
                alert("When product units are selected, at least one unit must have a barcode.");
                return;
            }
            finalBarcode = unitDetails[unitWithBarcode].barcode;
        }

        const definedUnits = selectedUnits.map(u => unitDetails[u]);

        onUpdate({
            ...productToEdit,
            name: formData.name,
            manufacturer: formData.manufacturer,
            category: formData.category,
            status: formData.status,
            barcode: finalBarcode,
            baseUnit: formData.baseUnit,
            baseQuantity: parseFloat(formData.baseQuantity) || 0,
            containerQuantity: parseFloat(formData.containerQuantity) || 0,
            containerUnit: formData.containerUnit,
            saleUnits: selectedUnits.join(', '),
            definedUnits: definedUnits,
            remarks: formData.remarks,
            hasBatchNumber: formData.hasBatchNumber,
            hasExpiryDate: formData.hasExpiryDate,
            updatedBy: 'Current User', 
            updatedAt: new Date().toISOString(),
            imageUrl: formData.imageUrl,
        });
        handleClose();
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    if (!isOpen && !isClosing) return null;

    const commonInputClasses = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClasses = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className={`fixed inset-0 bg-black z-[80] flex justify-center items-center p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100 bg-opacity-50' : 'opacity-0'}`}>
            <div className={`${theme === 'dark' ? 'bg-slate-900' : 'bg-white'} rounded-lg shadow-xl w-full max-w-3xl flex flex-col transition-all duration-300 ease-in-out ${isOpen && !isClosing ? 'scale-100 opacity-100' : 'scale-95 opacity-0'} max-h-[90vh]`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>Edit Product</h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* Image Uploader */}
                    <div className="flex flex-col items-center justify-center p-4 border-2 border-dashed rounded-lg border-slate-300 dark:border-slate-700 hover:border-yellow-500 transition-colors">
                        {formData.imageUrl ? (
                            <div className="relative group w-40 h-40">
                                <img src={formData.imageUrl} alt="Product preview" className="w-full h-full object-cover rounded-md" />
                                <label className="absolute inset-0 flex items-center justify-center bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer rounded-md">
                                    <Icon name="camera" className="h-8 w-8 text-white" />
                                    <input type="file" className="hidden" accept="image/*" onChange={handleImageChange} />
                                </label>
                                <button 
                                    onClick={() => setFormData(prev => ({ ...prev, imageUrl: '' }))}
                                    className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600 transition-colors"
                                >
                                    <Icon name="x-mark" className="h-4 w-4" />
                                </button>
                            </div>
                        ) : (
                            <label className="cursor-pointer flex flex-col items-center justify-center space-y-2">
                                <div className="p-3 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                                    <Icon name="camera" className="h-8 w-8" />
                                </div>
                                <span className="text-sm font-medium text-slate-600 dark:text-slate-400">Upload Product Image</span>
                                <input type="file" className="hidden" accept="image/*" onChange={handleImageChange} />
                            </label>
                        )}
                    </div>

                    {/* General Info */}
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className={labelClasses}>Manufacturer<span className="text-red-500">*</span></label>
                            <select name="manufacturer" value={formData.manufacturer} onChange={handleChange} className={commonInputClasses}>
                                <option value="">Select Manufacturer</option>
                                {manufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className={labelClasses}>Name<span className="text-red-500">*</span></label>
                            <input type="text" name="name" value={formData.name} onChange={handleChange} className={commonInputClasses} placeholder="Product Name" />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Category<span className="text-red-500">*</span></label>
                                <select name="category" value={formData.category} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select Category</option>
                                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Production status<span className="text-red-500">*</span></label>
                                <select name="status" value={formData.status} onChange={handleChange} className={commonInputClasses}>
                                    <option value="ACTIVE">Active</option>
                                    <option value="INACTIVE">Inactive</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Metrics */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Metrics</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Base Unit<span className="text-red-500">*</span></label>
                                <select name="baseUnit" value={formData.baseUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Base unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Base quantity<span className="text-red-500">*</span></label>
                                <input type="number" name="baseQuantity" value={formData.baseQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 20 (grams/ml)" />
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Container quantity</label>
                                <input type="number" name="containerQuantity" value={formData.containerQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 12 (items in container)" />
                            </div>
                            <div>
                                <label className={labelClasses}>Container Unit</label>
                                <select name="containerUnit" value={formData.containerUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Container Unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>

                         {/* Multi-select Product Units */}
                        <div className="mb-4">
                            <label className={labelClasses}>Product units<span className="text-red-500">*</span></label>
                            <div className="relative" ref={unitDropdownRef}>
                                <div 
                                    className={`w-full rounded-md border shadow-sm px-3 py-2 text-sm min-h-[38px] flex flex-wrap gap-2 items-center cursor-pointer focus-within:ring-1 focus-within:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600' : 'bg-white border-slate-300'}`}
                                    onClick={() => setIsUnitDropdownOpen(!isUnitDropdownOpen)}
                                >
                                    {selectedUnits.length === 0 && <span className="text-gray-400">Select units</span>}
                                    {selectedUnits.map(unit => (
                                        <span key={unit} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-yellow-100 text-yellow-800 border border-yellow-200">
                                            {unit}
                                            <button 
                                                type="button"
                                                onClick={(e) => { e.stopPropagation(); handleUnitToggle(unit); }}
                                                className="ml-1 text-yellow-900 hover:text-yellow-600 focus:outline-none"
                                            >
                                                <Icon name="x-mark" className="h-3 w-3" />
                                            </button>
                                        </span>
                                    ))}
                                    <div className="ml-auto"><Icon name="chevron-down" className="h-4 w-4 text-gray-400" /></div>
                                </div>
                                {isUnitDropdownOpen && (
                                    <div className={`absolute z-10 mt-1 w-full rounded-md shadow-lg max-h-48 overflow-auto border ${theme === 'dark' ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-300'}`}>
                                        {availableProductUnits.map(unit => (
                                            <div 
                                                key={unit} 
                                                className={`px-3 py-2 cursor-pointer text-sm flex items-center justify-between ${theme === 'dark' ? 'hover:bg-slate-700 text-slate-200' : 'hover:bg-slate-100 text-slate-800'} ${selectedUnits.includes(unit) ? 'bg-yellow-500/10' : ''}`}
                                                onClick={() => handleUnitToggle(unit)}
                                            >
                                                {unit}
                                                {selectedUnits.includes(unit) && <Icon name="check-circle" className="h-4 w-4 text-yellow-500" />}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Dynamic Unit Inputs */}
                        {selectedUnits.length > 0 && (
                            <div className="space-y-3 mb-4">
                                <div className="grid grid-cols-3 gap-4">
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Unit name*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Quantity*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Barcode</label>
                                </div>
                                {selectedUnits.map(unit => (
                                    <div key={unit} className="grid grid-cols-3 gap-4">
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.unitName || unit} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'unitName', e.target.value)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="number" 
                                            value={unitDetails[unit]?.quantity || 1} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'quantity', parseFloat(e.target.value) || 0)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.barcode || ''} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'barcode', e.target.value)}
                                            className={commonInputClasses} 
                                        />
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Tracking Settings & Remarks */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Tracking</h3>
                        <div className="space-y-4 mb-6">
                             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <Toggle 
                                    label="Batch Number Tracking" 
                                    description="Enable to track batch #."
                                    checked={formData.hasBatchNumber} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasBatchNumber: val}))} 
                                    theme={theme} 
                                />
                                <Toggle 
                                    label="Expiry Date Tracking" 
                                    description="Enable to track expiry."
                                    checked={formData.hasExpiryDate} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasExpiryDate: val}))} 
                                    theme={theme} 
                                />
                            </div>
                        </div>

                        <div>
                            <label className={labelClasses}>Remarks</label>
                            <textarea name="remarks" value={formData.remarks} onChange={handleChange} rows={3} className={commonInputClasses}></textarea>
                        </div>
                    </div>
                </div>

                <div className={`flex justify-end items-center p-6 border-t rounded-b-lg ${theme === 'dark' ? 'border-slate-700 bg-black/50' : 'border-slate-200 bg-slate-100'}`}>
                    <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm mr-3 ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                        Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                        <Icon name="check-circle" className="h-4 w-4 mr-2" />
                        Update
                    </button>
                </div>
            </div>
        </div>
    );
};

export default EditProductModal;

import React, { useState, useMemo } from 'react';
import { Theme, ProductDefinition, ActiveView } from '../types';
import { mockProductDefinitions } from '../data';
import Icon, { IconName } from './Icon';
import AddProductModal from './AddProductModal';
import EditProductModal from './EditProductModal';
import ProductShopsModal from './ProductShopsModal';

interface ProductsPageProps {
    theme: Theme;
    onNavigate: (view: ActiveView) => void;
}

const SummaryCard: React.FC<{ title: string; value: string; icon: IconName; theme: Theme; color?: string }> = ({ title, value, icon, theme, color = 'text-slate-900' }) => (
    <div className={`p-4 rounded-lg shadow-sm border flex items-center justify-between ${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'}`}>
        <div>
            <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{title}</p>
            <p className={`text-xl font-bold mt-1 ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>{value}</p>
        </div>
        <div className={`p-2 rounded-md ${theme === 'dark' ? 'bg-yellow-500 text-slate-900' : 'bg-yellow-400 text-slate-900'}`}>
            <Icon name={icon} className={`h-6 w-6`} />
        </div>
    </div>
);

const ProductsPage: React.FC<ProductsPageProps> = ({ theme, onNavigate }) => {
    const [products, setProducts] = useState<ProductDefinition[]>(mockProductDefinitions);
    const [searchTerm, setSearchTerm] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [isFilterOpen, setIsFilterOpen] = useState(false);
    const [expandedProductId, setExpandedProductId] = useState<number | null>(null);
    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [productToEdit, setProductToEdit] = useState<ProductDefinition | null>(null);
    const [selectedProductForShops, setSelectedProductForShops] = useState<{name: string, id: number} | null>(null);
    const ITEMS_PER_PAGE = 10;

    // Advanced Filters State
    const [filterCountry, setFilterCountry] = useState('');
    const [filterStatus, setFilterStatus] = useState('');
    const [filterCreatedBy, setFilterCreatedBy] = useState('');
    const [filterManufacturer, setFilterManufacturer] = useState('');
    const [filterCategory, setFilterCategory] = useState('');
    const [filterContainerUnit, setFilterContainerUnit] = useState('');
    const [filterPackageUnit, setFilterPackageUnit] = useState('');
    const [filterStartDate, setFilterStartDate] = useState('');
    const [filterEndDate, setFilterEndDate] = useState('');

    // Derive unique options for dropdowns
    const uniqueCountries = useMemo(() => [...new Set(products.map(p => p.country).filter(Boolean))].sort(), [products]);
    const uniqueManufacturers = useMemo(() => [...new Set(products.map(p => p.manufacturer).filter(Boolean))].sort(), [products]);
    const uniqueCategories = useMemo(() => [...new Set(products.map(p => p.category).filter(Boolean))].sort(), [products]);
    const uniqueCreators = useMemo(() => [...new Set(products.map(p => p.createdBy).filter(Boolean))].sort(), [products]);
    const uniqueContainerUnits = useMemo(() => [...new Set(products.map(p => p.containerUnit).filter(Boolean))].sort(), [products]);

    // Parse package units (saleUnits is comma separated string in mock data)
    const uniquePackageUnits = useMemo(() => {
        const allUnits = products.flatMap(p => p.saleUnits ? p.saleUnits.split(',').map(u => u.trim()) : []);
        return [...new Set(allUnits)].filter(Boolean).sort();
    }, [products]);

    const filteredProducts = useMemo(() => {
        return products.filter(p => {
            // Text Search
            const matchesSearch = 
                p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                p.sn.toLowerCase().includes(searchTerm.toLowerCase()) ||
                p.barcode.toLowerCase().includes(searchTerm.toLowerCase()) ||
                p.manufacturer.toLowerCase().includes(searchTerm.toLowerCase());

            if (!matchesSearch) return false;

            // Advanced Filters
            if (filterCountry && p.country !== filterCountry) return false;
            if (filterStatus && p.status !== filterStatus) return false;
            if (filterCreatedBy && p.createdBy !== filterCreatedBy) return false;
            if (filterManufacturer && p.manufacturer !== filterManufacturer) return false;
            if (filterCategory && p.category !== filterCategory) return false;
            if (filterContainerUnit && p.containerUnit !== filterContainerUnit) return false;

            // Package unit is a contains check since saleUnits is a list string
            if (filterPackageUnit && (!p.saleUnits || !p.saleUnits.includes(filterPackageUnit))) return false;

            if (filterStartDate) {
                const start = new Date(filterStartDate);
                const created = new Date(p.createdAt || '');
                if (created < start) return false;
            }
            if (filterEndDate) {
                const end = new Date(filterEndDate);
                end.setHours(23, 59, 59, 999);
                const created = new Date(p.createdAt || '');
                if (created > end) return false;
            }

            return true;
        });
    }, [products, searchTerm, filterCountry, filterStatus, filterCreatedBy, filterManufacturer, filterCategory, filterContainerUnit, filterPackageUnit, filterStartDate, filterEndDate]);

    const handleResetFilters = () => {
        setFilterCountry('');
        setFilterStatus('');
        setFilterCreatedBy('');
        setFilterManufacturer('');
        setFilterCategory('');
        setFilterContainerUnit('');
        setFilterPackageUnit('');
        setFilterStartDate('');
        setFilterEndDate('');
        setSearchTerm('');
        setCurrentPage(1);
    };

    const handleAddProduct = (newProductData: Omit<ProductDefinition, 'id' | 'sn' | 'createdAt' | 'updatedAt' | 'updatedBy'>) => {
        const newId = Math.max(...products.map(p => p.id), 0) + 1;
        const newProduct: ProductDefinition = {
            ...newProductData,
            id: newId,
            sn: `PDT${Math.floor(Math.random() * 10000000)}`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            updatedBy: 'Paul Mboya', // Mock current user
            createdBy: 'Paul Mboya',
        };
        setProducts([newProduct, ...products]);
    };

    const handleEditClick = (product: ProductDefinition) => {
        setProductToEdit(product);
        setIsEditModalOpen(true);
    };

    const handleUpdateProduct = (updatedProduct: ProductDefinition) => {
        setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    };

    const paginatedProducts = useMemo(() => {
        const start = (currentPage - 1) * ITEMS_PER_PAGE;
        return filteredProducts.slice(start, start + ITEMS_PER_PAGE);
    }, [filteredProducts, currentPage]);

    const totalPages = Math.ceil(filteredProducts.length / ITEMS_PER_PAGE);
    const startRecord = filteredProducts.length > 0 ? (currentPage - 1) * ITEMS_PER_PAGE + 1 : 0;
    const endRecord = Math.min(currentPage * ITEMS_PER_PAGE, filteredProducts.length);

    const handlePageChange = (page: number) => {
        if (page >= 1 && page <= totalPages) {
            setCurrentPage(page);
        }
    };

    const toggleExpand = (id: number) => {
        setExpandedProductId(expandedProductId === id ? null : id);
    };

    const formatDate = (dateString?: string) => {
        if (!dateString) return 'N/A';
        return new Date(dateString).toLocaleString('en-US', {
            weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: 'numeric', hour12: true
        });
    }

    const inputClass = `w-full text-sm px-3 py-2 rounded-md border outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <>
        <AddProductModal 
            isOpen={isAddModalOpen}
            onClose={() => setIsAddModalOpen(false)}
            onSave={handleAddProduct}
            theme={theme}
        />
        <EditProductModal 
            isOpen={isEditModalOpen}
            onClose={() => setIsEditModalOpen(false)}
            onUpdate={handleUpdateProduct}
            productToEdit={productToEdit}
            theme={theme}
        />
        <ProductShopsModal 
            isOpen={!!selectedProductForShops} 
            onClose={() => setSelectedProductForShops(null)} 
            product={selectedProductForShops} 
            theme={theme} 
        />

        <div className="space-y-6 h-full flex flex-col">
            {/* Summary Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 flex-shrink-0">
                <SummaryCard title="Countries" value={uniqueCountries.length.toString()} icon="countries" theme={theme} />
                <SummaryCard title="Manufacturers" value={uniqueManufacturers.length.toString()} icon="shop-mgt" theme={theme} />
                <SummaryCard title="Categories" value={uniqueCategories.length.toString()} icon="globe" theme={theme} />
                <SummaryCard title="Products" value={products.length.toLocaleString()} icon="stock-listing" theme={theme} />
            </div>

            {/* Filter Section */}
            <div className={`${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'} rounded-lg shadow-sm border flex-shrink-0`}>
                <button 
                    onClick={() => setIsFilterOpen(!isFilterOpen)}
                    className={`w-full px-4 py-3 flex justify-between items-center text-sm font-bold ${theme === 'dark' ? 'text-slate-300 hover:bg-slate-800' : 'text-slate-700 hover:bg-slate-50'}`}
                >
                    <span>Filter</span>
                    <Icon name="chevron-right" className={`h-4 w-4 transition-transform ${isFilterOpen ? 'rotate-90' : ''}`} />
                </button>
                {isFilterOpen && (
                    <div className={`p-6 border-t ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {/* Row 1 */}
                            <div>
                                <label className={labelClass}>Country</label>
                                <select value={filterCountry} onChange={(e) => setFilterCountry(e.target.value)} className={inputClass}>
                                    <option value="">Select Country</option>
                                    {uniqueCountries.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClass}>Status</label>
                                <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)} className={inputClass}>
                                    <option value="">Select status</option>
                                    <option value="ACTIVE">Active</option>
                                    <option value="INACTIVE">Inactive</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelClass}>Created by</label>
                                <select value={filterCreatedBy} onChange={(e) => setFilterCreatedBy(e.target.value)} className={inputClass}>
                                    <option value="">Select user</option>
                                    {uniqueCreators.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>

                            {/* Row 2 */}
                            <div>
                                <label className={labelClass}>Manufacturer</label>
                                <select value={filterManufacturer} onChange={(e) => setFilterManufacturer(e.target.value)} className={inputClass}>
                                    <option value="">Select manufacturer</option>
                                    {uniqueManufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClass}>Category</label>
                                <select value={filterCategory} onChange={(e) => setFilterCategory(e.target.value)} className={inputClass}>
                                    <option value="">Select category</option>
                                    {uniqueCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClass}>Container Unit</label>
                                <select value={filterContainerUnit} onChange={(e) => setFilterContainerUnit(e.target.value)} className={inputClass}>
                                    <option value="">Select container unit</option>
                                    {uniqueContainerUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>

                            {/* Row 3 */}
                            <div>
                                <label className={labelClass}>Package Unit</label>
                                <select value={filterPackageUnit} onChange={(e) => setFilterPackageUnit(e.target.value)} className={inputClass}>
                                    <option value="">Select package unit</option>
                                    {uniquePackageUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClass}>Start Date</label>
                                <input type="date" value={filterStartDate} onChange={(e) => setFilterStartDate(e.target.value)} className={inputClass} />
                            </div>
                            <div>
                                <label className={labelClass}>End Date</label>
                                <input type="date" value={filterEndDate} onChange={(e) => setFilterEndDate(e.target.value)} className={inputClass} />
                            </div>
                        </div>

                        <div className="flex justify-end gap-3 mt-6">
                            <button 
                                onClick={handleResetFilters}
                                className={`px-4 py-2 text-sm font-medium border rounded-md flex items-center gap-2 transition-colors ${theme === 'dark' ? 'border-slate-600 text-slate-300 hover:bg-slate-700' : 'border-slate-300 text-slate-600 hover:bg-slate-100'}`}
                            >
                                <Icon name="x-mark" className="h-4 w-4" />
                                Clear
                            </button>
                            <button className="px-4 py-2 text-sm font-medium bg-black text-yellow-500 rounded-md flex items-center gap-2 hover:bg-slate-900 transition-colors border border-black">
                                <Icon name="check-circle" className="h-4 w-4" />
                                Filter
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Products Table Section */}
            <div className={`${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'} rounded-lg shadow-sm border flex-grow flex flex-col overflow-hidden`}>
                <div className={`p-4 border-b flex flex-col md:flex-row items-center justify-between gap-4 ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-lg font-bold border-b-2 border-yellow-500 pb-1 ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>Products</h2>

                    <div className="flex items-center gap-3 w-full md:w-auto">
                        <div className="relative flex-grow md:flex-grow-0 md:w-64">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                <Icon name="search" className="h-4 w-4 text-slate-400" />
                            </div>
                            <input
                                type="text"
                                placeholder="Search"
                                className={`pl-9 pr-3 py-2 text-sm border rounded-md w-full md:w-64 focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300'}`}
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                            <div className={`absolute inset-y-0 right-0 pr-2 flex items-center ${theme === 'dark' ? 'bg-slate-700' : 'bg-slate-100'} my-1 mr-1 rounded px-2`}>
                                <Icon name="search" className="h-4 w-4 text-slate-500" />
                            </div>
                        </div>
                        <button 
                            onClick={() => setIsAddModalOpen(true)}
                            className="px-4 py-2 bg-black text-yellow-500 text-sm font-medium rounded-md hover:bg-slate-900 transition-colors flex items-center gap-2 whitespace-nowrap"
                        >
                            <Icon name="plus" className="h-4 w-4" />
                            New
                        </button>
                    </div>
                </div>

                <div className="overflow-x-auto flex-grow">
                    <table className={`min-w-full divide-y ${theme === 'dark' ? 'divide-slate-700' : 'divide-slate-200'}`}>
                        <thead className={theme === 'dark' ? 'bg-slate-800' : 'bg-slate-50'}>
                            <tr>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>#</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Image</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>SN</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Product</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Barcode</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Manufacturer</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Listed Shops</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Created by</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Status</th>
                                <th scope="col" className={`px-6 py-3 text-left text-xs font-bold uppercase tracking-wider ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Actions</th>
                            </tr>
                        </thead>
                        <tbody className={`divide-y ${theme === 'dark' ? 'bg-slate-900 divide-slate-700' : 'bg-white divide-slate-200'}`}>
                            {paginatedProducts.map((product, index) => (
                                <React.Fragment key={product.id}>
                                    <tr className={theme === 'dark' ? 'hover:bg-slate-800/50' : 'hover:bg-slate-50'}>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                                            <div className="flex items-center gap-3">
                                                <span className={`${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>{startRecord + index}</span>
                                                <button 
                                                    onClick={() => toggleExpand(product.id)}
                                                    className={`p-1 rounded-full transition-transform ${expandedProductId === product.id ? 'rotate-180' : ''} ${theme === 'dark' ? 'hover:bg-slate-700 text-slate-400' : 'hover:bg-slate-200 text-slate-500'}`}
                                                >
                                                    <Icon name="chevron-down" className="h-4 w-4" />
                                                </button>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap">
                                            <div className="w-10 h-10 rounded border overflow-hidden bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700 flex items-center justify-center">
                                                {product.imageUrl ? (
                                                    <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                                                ) : (
                                                    <Icon name="stock-listing" className="h-5 w-5 text-slate-400" />
                                                )}
                                            </div>
                                        </td>
                                        <td className={`px-6 py-4 whitespace-nowrap text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>{product.sn}</td>
                                        <td className={`px-6 py-4 text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.name}</td>
                                        <td className={`px-6 py-4 whitespace-nowrap text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>{product.barcode}</td>
                                        <td className={`px-6 py-4 text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>{product.manufacturer}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); setSelectedProductForShops({ name: product.name, id: product.id }); }}
                                                className={`w-8 h-8 flex items-center justify-center rounded-md text-xs font-bold transition-colors text-white ${
                                                    theme === 'dark'
                                                    ? 'bg-slate-700 hover:bg-yellow-500 hover:text-slate-900'
                                                    : 'bg-slate-600 hover:bg-yellow-500 hover:text-slate-900'
                                                }`}
                                            >
                                                {Math.floor((product.id * 17) % 20) + 5}
                                            </button>
                                        </td>
                                        <td className={`px-6 py-4 whitespace-nowrap text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}>{product.createdBy}</td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                                            <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${product.status === 'ACTIVE' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                                                {product.status}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 whitespace-nowrap text-sm">
                                            <div className="flex items-center space-x-3">
                                                <button onClick={() => handleEditClick(product)} className="text-green-500 hover:text-green-600"><Icon name="edit" className="h-4 w-4" /></button>
                                                <button className="text-red-500 hover:text-red-600"><Icon name="trash" className="h-4 w-4" /></button>
                                            </div>
                                        </td>
                                    </tr>
                                    {expandedProductId === product.id && (
                                        <tr>
                                            <td colSpan={10} className={`px-6 py-6 ${theme === 'dark' ? 'bg-slate-800/30' : 'bg-slate-100'}`}>
                                                <div className="grid grid-cols-1 md:grid-cols-4 gap-y-4 gap-x-8">
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Category:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.category || 'Unknown'}</p>
                                                    </div>
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Base unit:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>
                                                            {product.baseUnit} {product.baseQuantity ? `(${product.baseQuantity})` : ''}
                                                        </p>
                                                    </div>

                                                    <div className="md:col-span-2">
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Sale Units</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.saleUnits || '-'}</p>
                                                    </div>

                                                    {/* New Tracking Info */}
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Batch Tracking:</p>
                                                        <div className={`text-sm font-medium mt-1`}>
                                                            {product.hasBatchNumber ? (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400">
                                                                    Active
                                                                </span>
                                                            ) : (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-400">
                                                                    Inactive
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Expiry Tracking:</p>
                                                        <div className={`text-sm font-medium mt-1`}>
                                                            {product.hasExpiryDate ? (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400">
                                                                    Active
                                                                </span>
                                                            ) : (
                                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-400">
                                                                    Inactive
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>

                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Country:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.country || 'Unknown'}</p>
                                                    </div>

                                                    {/* Spacer or additional field if needed */}
                                                    <div className="hidden md:block"></div> 

                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Date created:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{formatDate(product.createdAt)}</p>
                                                    </div>
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Created by:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.createdBy}</p>
                                                    </div>
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Date last changed:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{formatDate(product.updatedAt)}</p>
                                                    </div>
                                                    <div>
                                                        <p className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Changed by:</p>
                                                        <p className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{product.updatedBy || '-'}</p>
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                        </tbody>
                    </table>
                </div>

                {/* Pagination */}
                <div className={`p-4 border-t flex justify-between items-center ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <p className={`text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
                        Showing {startRecord} to {endRecord} of {filteredProducts.length.toLocaleString()} records
                        <select className={`ml-2 p-1 rounded border text-xs ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-300' : 'bg-white border-slate-300 text-slate-700'}`}>
                            <option>10</option>
                            <option>20</option>
                            <option>50</option>
                        </select>
                    </p>
                    <div className="flex items-center space-x-2">
                        <button 
                            onClick={() => handlePageChange(1)}
                            disabled={currentPage === 1}
                            className={`p-1 text-xs font-medium hover:underline disabled:opacity-50 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}
                        >
                            <Icon name="chevron-left" className="h-3 w-3 inline mr-1" />
                            <Icon name="chevron-left" className="h-3 w-3 inline -ml-2" />
                        </button>
                        <button 
                            onClick={() => handlePageChange(currentPage - 1)}
                            disabled={currentPage === 1}
                            className={`p-1 rounded-md hover:bg-gray-100 dark:hover:bg-slate-800 disabled:opacity-50`}
                        >
                            <Icon name="chevron-left" className={`h-4 w-4 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`} />
                        </button>

                        <span className={`px-3 py-1 rounded-md text-sm font-bold bg-yellow-400 text-slate-900`}>
                            {currentPage}
                        </span>

                        {currentPage < totalPages && (
                             <button 
                                onClick={() => handlePageChange(currentPage + 1)}
                                className={`px-3 py-1 rounded-md text-sm font-medium hover:bg-gray-100 dark:hover:bg-slate-800 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-600'}`}
                            >
                                {currentPage + 1}
                            </button>
                        )}

                        <button 
                            onClick={() => handlePageChange(currentPage + 1)}
                            disabled={currentPage === totalPages}
                            className={`p-1 rounded-md hover:bg-gray-100 dark:hover:bg-slate-800 disabled:opacity-50`}
                        >
                            <Icon name="chevron-right" className={`h-4 w-4 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`} />
                        </button>
                        <button 
                            onClick={() => handlePageChange(totalPages)}
                            disabled={currentPage === totalPages}
                            className={`p-1 text-xs font-medium hover:underline disabled:opacity-50 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}
                        >
                            <Icon name="chevron-right" className="h-3 w-3 inline mr-1" />
                            <Icon name="chevron-right" className="h-3 w-3 inline -ml-2" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
        </>
    );
};

export default ProductsPage;

import React, { useState, useEffect, useRef } from 'react';
import { Theme, ProductDefinition, ProductUnitDefinition, Shop } from '../types';
import Icon from './Icon';
import { availableProductUnits, mockShops } from '../data';

interface AddProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (product: Omit<ProductDefinition, 'id' | 'sn' | 'createdAt' | 'updatedAt' | 'updatedBy'>) => void;
  theme: Theme;
}

const manufacturers = ['Unknown Manufacturer', 'Samsung', 'LG', 'Sony', 'Apple', 'Coca Cola', 'Pepsi'];
const categories = ['Adhesives', 'Cosmetics', 'Electronics', 'Chemicals', 'Household', 'Industrial', 'Beverages'];
const warehouses = [
    { id: 101, name: 'Main Warehouse - Kampala' },
    { id: 102, name: 'Distribution Center - Jinja' },
    { id: 103, name: 'Storage Unit B' }
];

const Toggle = ({ label, description, checked, onChange, theme }: { label: string, description?: string, checked: boolean, onChange: (val: boolean) => void, theme: Theme }) => (
    <div className="flex items-center justify-between py-2">
        <div>
            <div className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{label}</div>
            {description && <div className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{description}</div>}
        </div>
        <button
            type="button"
            onClick={() => onChange(!checked)}
            className={`ml-4 relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-yellow-500' : (theme === 'dark' ? 'bg-slate-600' : 'bg-slate-200')}`}
        >
            <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </button>
    </div>
);

const AddProductModal: React.FC<AddProductModalProps> = ({ isOpen, onClose, onSave, theme }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [formData, setFormData] = useState({
        manufacturer: '',
        name: '',
        category: '',
        status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE',
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        remarks: '',
        country: '',
        hasBatchNumber: false,
        hasExpiryDate: false,
        locationType: 'Shop' as 'Shop' | 'Warehouse',
        locationId: '',
        imageUrl: '',
    });

    // Multi-select units state
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isUnitDropdownOpen]);

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
            // Reset form
            setFormData({
                manufacturer: '',
                name: '',
                category: '',
                status: 'ACTIVE',
                baseUnit: '',
                baseQuantity: '',
                containerQuantity: '',
                containerUnit: '',
                remarks: '',
                country: '',
                hasBatchNumber: false,
                hasExpiryDate: false,
                locationType: 'Shop',
                locationId: '',
                imageUrl: '',
            });
            setSelectedUnits([]);
            setUnitDetails({});
        }, 300);
    };

    const handleSave = () => {
        if (!formData.name || !formData.manufacturer || !formData.category || !formData.baseUnit) {
            alert("Please fill in required fields (Manufacturer, Name, Category, Base Unit).");
            return;
        }

        let finalBarcode = '0000';

        // Validation for unit barcodes
        if (selectedUnits.length > 0) {
            const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
            if (!unitWithBarcode) {
                alert("When product units are selected, at least one unit must have a barcode.");
                return;
            }
            // Use the first valid barcode found as the main barcode if needed, or simply proceed
            finalBarcode = unitDetails[unitWithBarcode].barcode;
        }

        // Convert unit details map to array for saving
        const definedUnits = selectedUnits.map(u => unitDetails[u]);

        onSave({
            name: formData.name,
            manufacturer: formData.manufacturer,
            category: formData.category,
            status: formData.status,
            barcode: finalBarcode, // Main barcode derived from units or default
            baseUnit: formData.baseUnit,
            baseQuantity: parseFloat(formData.baseQuantity) || 0,
            containerQuantity: parseFloat(formData.containerQuantity) || 0,
            containerUnit: formData.containerUnit,
            saleUnits: selectedUnits.join(', '), // Store as comma separated string for display compat
            definedUnits: definedUnits,
            remarks: formData.remarks,
            country: formData.country || 'Unknown', 
            hasBatchNumber: formData.hasBatchNumber,
            hasExpiryDate: formData.hasExpiryDate,
            createdBy: 'Current User',
            imageUrl: formData.imageUrl,
        });
        handleClose();
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    if (!isOpen && !isClosing) return null;

    const commonInputClasses = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClasses = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className={`fixed inset-0 bg-black z-[80] flex justify-center items-center p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100 bg-opacity-50' : 'opacity-0'}`}>
            <div className={`${theme === 'dark' ? 'bg-slate-900' : 'bg-white'} rounded-lg shadow-xl w-full max-w-3xl flex flex-col transition-all duration-300 ease-in-out ${isOpen && !isClosing ? 'scale-100 opacity-100' : 'scale-95 opacity-0'} max-h-[90vh]`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>Product</h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* General Info */}
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className={labelClasses}>Manufacturer<span className="text-red-500">*</span></label>
                            <select name="manufacturer" value={formData.manufacturer} onChange={handleChange} className={commonInputClasses}>
                                <option value="">Select Manufacturer</option>
                                {manufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className={labelClasses}>Name<span className="text-red-500">*</span></label>
                            <input type="text" name="name" value={formData.name} onChange={handleChange} className={commonInputClasses} placeholder="Product Name" />
                        </div>

                        {/* Type and Location Row */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Location Type</label>
                                <select 
                                    name="locationType" 
                                    value={formData.locationType} 
                                    onChange={(e) => setFormData(prev => ({ ...prev, locationType: e.target.value as any, locationId: '' }))} 
                                    className={commonInputClasses}
                                >
                                    <option value="Shop">Shop</option>
                                    <option value="Warehouse">Warehouse</option>
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>{formData.locationType}</label>
                                <select name="locationId" value={formData.locationId} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select {formData.locationType}</option>
                                    {formData.locationType === 'Shop' 
                                        ? mockShops.map(s => <option key={s.id} value={s.id}>{s.name}</option>)
                                        : warehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)
                                    }
                                </select>
                            </div>
                        </div>

                        {/* Category and Status Row */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Category<span className="text-red-500">*</span></label>
                                <select name="category" value={formData.category} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select Category</option>
                                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Production status<span className="text-red-500">*</span></label>
                                <select name="status" value={formData.status} onChange={handleChange} className={commonInputClasses}>
                                    <option value="ACTIVE">Active</option>
                                    <option value="INACTIVE">Inactive</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Metrics */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Metrics</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Base Unit<span className="text-red-500">*</span></label>
                                <select name="baseUnit" value={formData.baseUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Base unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Base quantity<span className="text-red-500">*</span></label>
                                <input type="number" name="baseQuantity" value={formData.baseQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 20 (grams/ml)" />
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Container quantity</label>
                                <input type="number" name="containerQuantity" value={formData.containerQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 12 (items in container)" />
                            </div>
                            <div>
                                <label className={labelClasses}>Container Unit</label>
                                <select name="containerUnit" value={formData.containerUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Container Unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>

                        {/* Multi-select Product Units */}
                        <div className="mb-4">
                            <label className={labelClasses}>Product units<span className="text-red-500">*</span></label>
                            <div className="relative" ref={unitDropdownRef}>
                                <div 
                                    className={`w-full rounded-md border shadow-sm px-3 py-2 text-sm min-h-[38px] flex flex-wrap gap-2 items-center cursor-pointer focus-within:ring-1 focus-within:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600' : 'bg-white border-slate-300'}`}
                                    onClick={() => setIsUnitDropdownOpen(!isUnitDropdownOpen)}
