                                            >
                                                {unit}
                                                {selectedUnits.includes(unit) && <Icon name="check-circle" className="h-4 w-4 text-yellow-500" />}
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Dynamic Unit Inputs */}
                        {selectedUnits.length > 0 && (
                            <div className="space-y-3 mb-4">
                                <div className="grid grid-cols-3 gap-4">
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Unit name*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Quantity*</label>
                                    <label className={`text-xs font-semibold ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Barcode</label>
                                </div>
                                {selectedUnits.map(unit => (
                                    <div key={unit} className="grid grid-cols-3 gap-4">
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.unitName || unit} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'unitName', e.target.value)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="number" 
                                            value={unitDetails[unit]?.quantity || 1} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'quantity', parseFloat(e.target.value) || 0)}
                                            className={commonInputClasses} 
                                        />
                                        <input 
                                            type="text" 
                                            value={unitDetails[unit]?.barcode || ''} 
                                            onChange={(e) => handleUnitDetailChange(unit, 'barcode', e.target.value)}
                                            className={commonInputClasses} 
                                            placeholder="Barcode"
                                        />
                                    </div>
                                ))}
                            </div>
                        )}

                    </div>

                    {/* Tracking Settings & Remarks */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Tracking</h3>
                        <div className="space-y-4 mb-4">
                             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <Toggle 
                                    label="Batch Number Tracking" 
                                    description="Enable to track batch #."
                                    checked={formData.hasBatchNumber} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasBatchNumber: val}))} 
                                    theme={theme} 
                                />
                                <Toggle 
                                    label="Expiry Date Tracking" 
                                    description="Enable to track expiry."
                                    checked={formData.hasExpiryDate} 
                                    onChange={(val) => setFormData(prev => ({...prev, hasExpiryDate: val}))} 
                                    theme={theme} 
                                />
                            </div>
                        </div>

                        {/* Image Uploader - Moved above remarks */}
                        <div className="mb-4">
                            <label className={labelClasses}>Product Image</label>
                            <div className="flex flex-col items-center justify-center p-4 border-2 border-dashed rounded-lg border-slate-300 dark:border-slate-700 hover:border-yellow-500 transition-colors">
                                {formData.imageUrl ? (
                                    <div className="relative group w-40 h-40">
                                        <img src={formData.imageUrl} alt="Product preview" className="w-full h-full object-cover rounded-md" />
                                        <button 
                                            onClick={() => setFormData(prev => ({ ...prev, imageUrl: '' }))}
                                            className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600 transition-colors"
                                        >
                                            <Icon name="x-mark" className="h-4 w-4" />
                                        </button>
                                    </div>
                                ) : (
                                    <label className="cursor-pointer flex flex-col items-center justify-center space-y-2 w-full">
                                        <div className="p-3 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
                                            <Icon name="camera" className="h-8 w-8" />
                                        </div>
                                        <span className="text-sm font-medium text-slate-600 dark:text-slate-400">Upload Product Image</span>
                                        <input type="file" className="hidden" accept="image/*" onChange={handleImageChange} />
                                    </label>
                                )}
                            </div>
                        </div>

                        <div>
                            <label className={labelClasses}>Remarks</label>
                            <textarea name="remarks" value={formData.remarks} onChange={handleChange} className={commonInputClasses} rows={3} placeholder="Product description"></textarea>
                        </div>
                    </div>
                </div>

                <div className={`flex justify-end items-center p-6 border-t rounded-b-lg ${theme === 'dark' ? 'border-slate-700 bg-black/50' : 'border-slate-200 bg-slate-100'}`}>
                    <button onClick={handleClose} className={`px-6 py-2.5 text-sm font-medium border rounded-md shadow-sm mr-3 ${theme === 'dark' ? 'text-slate-300 bg-transparent border-slate-600 hover:bg-slate-700' : 'text-slate-700 bg-white border-slate-300 hover:bg-slate-50'}`}>
                        Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2.5 text-sm font-semibold text-slate-900 bg-yellow-500 border border-transparent rounded-md shadow-sm hover:bg-yellow-600 flex items-center">
                        <Icon name="check-circle" className="h-4 w-4 mr-2" />
                        Save
                    </button>
                </div>
            </div>
        </div>
    );
};

export default AddProductModal;

import React, { useState, useEffect, useRef } from 'react';
import { Theme, ProductDefinition, ProductUnitDefinition } from '../types';
import Icon from './Icon';
import { availableProductUnits } from '../data';

interface EditProductModalProps {
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (product: ProductDefinition) => void;
  productToEdit: ProductDefinition | null;
  theme: Theme;
}

const manufacturers = ['Unknown Manufacturer', 'Samsung', 'LG', 'Sony', 'Apple', 'Coca Cola', 'Pepsi'];
const categories = ['Adhesives', 'Cosmetics', 'Electronics', 'Chemicals', 'Household', 'Industrial', 'Beverages'];

const Toggle = ({ label, description, checked, onChange, theme }: { label: string, description?: string, checked: boolean, onChange: (val: boolean) => void, theme: Theme }) => (
    <div className="flex items-center justify-between py-2">
        <div>
            <div className={`text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>{label}</div>
            {description && <div className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-500'}`}>{description}</div>}
        </div>
        <button
            type="button"
            onClick={() => onChange(!checked)}
            className={`ml-4 relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${checked ? 'bg-yellow-500' : (theme === 'dark' ? 'bg-slate-600' : 'bg-slate-200')}`}
        >
            <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
        </button>
    </div>
);

const EditProductModal: React.FC<EditProductModalProps> = ({ isOpen, onClose, onUpdate, productToEdit, theme }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [formData, setFormData] = useState({
        manufacturer: '',
        name: '',
        category: '',
        status: 'ACTIVE' as 'ACTIVE' | 'INACTIVE',
        barcode: '',
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        remarks: '',
        hasBatchNumber: false,
        hasExpiryDate: false,
        imageUrl: '',
    });

    // Multi-select units state
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (isOpen && productToEdit) {
            setFormData({
                manufacturer: productToEdit.manufacturer,
                name: productToEdit.name,
                category: productToEdit.category || '',
                status: productToEdit.status,
                barcode: productToEdit.barcode,
                baseUnit: productToEdit.baseUnit || '',
                baseQuantity: productToEdit.baseQuantity?.toString() || '',
                containerQuantity: productToEdit.containerQuantity?.toString() || '',
                containerUnit: productToEdit.containerUnit || '',
                remarks: productToEdit.remarks || '',
                hasBatchNumber: !!productToEdit.hasBatchNumber,
                hasExpiryDate: !!productToEdit.hasExpiryDate,
                imageUrl: productToEdit.imageUrl || '',
            });

            // Populate units
            const unitsList = productToEdit.definedUnits ? productToEdit.definedUnits.map(u => u.unitName) : (productToEdit.saleUnits ? productToEdit.saleUnits.split(',').map(s => s.trim()) : []);
            setSelectedUnits(unitsList);

            const details: Record<string, ProductUnitDefinition> = {};
            if (productToEdit.definedUnits) {
                productToEdit.definedUnits.forEach(u => {
                    details[u.unitName] = u;
                });
            } else {
                // Fallback if only saleUnits string exists
                unitsList.forEach(u => {
                    details[u] = { unitName: u, quantity: 1, barcode: '' };
                });
            }
            setUnitDetails(details);
        }
    }, [isOpen, productToEdit]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isUnitDropdownOpen]);

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
        }, 300);
    };

    const handleSave = () => {
        if (!productToEdit) return;

        if (!formData.name || !formData.manufacturer || !formData.category || !formData.baseUnit) {
            alert("Please fill in required fields (Manufacturer, Name, Category, Base Unit).");
            return;
        }

        let finalBarcode = formData.barcode || '0000';

        // Validation for unit barcodes
        if (selectedUnits.length > 0) {
            const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
            if (!unitWithBarcode) {
                alert("When product units are selected, at least one unit must have a barcode.");
                return;
            }
            finalBarcode = unitDetails[unitWithBarcode].barcode;
        }

        const definedUnits = selectedUnits.map(u => unitDetails[u]);

        onUpdate({
            ...productToEdit,
            name: formData.name,
            manufacturer: formData.manufacturer,
            category: formData.category,
            status: formData.status,
            barcode: finalBarcode,
            baseUnit: formData.baseUnit,
            baseQuantity: parseFloat(formData.baseQuantity) || 0,
            containerQuantity: parseFloat(formData.containerQuantity) || 0,
            containerUnit: formData.containerUnit,
            saleUnits: selectedUnits.join(', '),
            definedUnits: definedUnits,
            remarks: formData.remarks,
            hasBatchNumber: formData.hasBatchNumber,
            hasExpiryDate: formData.hasExpiryDate,
            updatedBy: 'Current User', 
            updatedAt: new Date().toISOString(),
            imageUrl: formData.imageUrl,
        });
        handleClose();
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    if (!isOpen && !isClosing) return null;

    const commonInputClasses = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200' : 'bg-white border-slate-300 text-slate-900'}`;
    const labelClasses = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className={`fixed inset-0 bg-black z-[80] flex justify-center items-center p-4 transition-opacity duration-300 ${isOpen && !isClosing ? 'opacity-100 bg-opacity-50' : 'opacity-0'}`}>
            <div className={`${theme === 'dark' ? 'bg-slate-900' : 'bg-white'} rounded-lg shadow-xl w-full max-w-3xl flex flex-col transition-all duration-300 ease-in-out ${isOpen && !isClosing ? 'scale-100 opacity-100' : 'scale-95 opacity-0'} max-h-[90vh]`}>
                <div className={`flex justify-between items-center p-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-900'}`}>Edit Product</h2>
                    <button onClick={handleClose} className={`${theme === 'dark' ? 'text-slate-400 hover:text-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
                        <Icon name="x-mark" className="h-6 w-6" />
                    </button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* General Info */}
                    <div className="grid grid-cols-1 gap-4">
                        <div>
                            <label className={labelClasses}>Manufacturer<span className="text-red-500">*</span></label>
                            <select name="manufacturer" value={formData.manufacturer} onChange={handleChange} className={commonInputClasses}>
                                <option value="">Select Manufacturer</option>
                                {manufacturers.map(m => <option key={m} value={m}>{m}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className={labelClasses}>Name<span className="text-red-500">*</span></label>
                            <input type="text" name="name" value={formData.name} onChange={handleChange} className={commonInputClasses} placeholder="Product Name" />
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className={labelClasses}>Category<span className="text-red-500">*</span></label>
                                <select name="category" value={formData.category} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Select Category</option>
                                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Production status<span className="text-red-500">*</span></label>
                                <select name="status" value={formData.status} onChange={handleChange} className={commonInputClasses}>
                                    <option value="ACTIVE">Active</option>
                                    <option value="INACTIVE">Inactive</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Metrics */}
                    <div>
                        <h3 className={`text-sm font-bold mb-4 border-b pb-2 ${theme === 'dark' ? 'text-slate-200 border-slate-700' : 'text-slate-800 border-slate-200'}`}>Metrics</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className={labelClasses}>Base Unit<span className="text-red-500">*</span></label>
                                <select name="baseUnit" value={formData.baseUnit} onChange={handleChange} className={commonInputClasses}>
                                    <option value="">Base unit</option>
                                    {availableProductUnits.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className={labelClasses}>Base quantity<span className="text-red-500">*</span></label>
                                <input type="number" name="baseQuantity" value={formData.baseQuantity} onChange={handleChange} className={commonInputClasses} placeholder="e.g. 20 (grams/ml)" />
