const OpeningStockModal: React.FC<OpeningStockModalProps> = ({ isOpen, onClose, onSave, theme, shops, productDefinitions }) => {
    const [isClosing, setIsClosing] = useState(false);
    const [activeStep, setActiveStep] = useState(1);
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [priceError, setPriceError] = useState<{ isOpen: boolean; message: string }>({ isOpen: false, message: '' });

    // Product Search State
    const [isProductDropdownOpen, setIsProductDropdownOpen] = useState(false);
    const [productSearch, setProductSearch] = useState('');
    const productDropdownRef = useRef<HTMLDivElement>(null);

    // Unit Selection State
    const [selectedUnits, setSelectedUnits] = useState<string[]>([]);
    const [unitDetails, setUnitDetails] = useState<Record<string, ProductUnitDefinition>>({});
    const [isUnitDropdownOpen, setIsUnitDropdownOpen] = useState(false);
    const unitDropdownRef = useRef<HTMLDivElement>(null);

    // Portions State for Step 2
    const [portions, setPortions] = useState<Portion[]>([]);

    // Form State
    const [formData, setFormData] = useState({
        // Step 1: Product Details
        locationType: 'Shop' as 'Shop' | 'Warehouse',
        locationId: '',
        productName: '',
        manufacturer: '',
        category: '',
        status: 'ACTIVE',
        baseUnit: '',
        baseQuantity: '',
        containerQuantity: '',
        containerUnit: '',
        description: '',
        hasBatchNumber: false,
        hasExpiryDate: false,
        imageUrl: '', // Added imageUrl to formData

        // Step 2: Stock Listing Info
        customName: '',
        defaultStockUnit: '', // New Field
        reportUnit: '',
        containerPortion: '',
        allowMix: false,
        listingRemarks: '', 

        // Step 3: Stock Information
        stockUnit: '',
        date: new Date().toISOString().split('T')[0],
        quantity: '',
        unitPrice: '', // Selling Price
        buyingPrice: '', // Cost
        batchNumber: '',
        expiryDate: '',
        supplier: 'Unknown',
        invoiceNumber: '',
    });

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (productDropdownRef.current && !productDropdownRef.current.contains(event.target as Node)) {
                setIsProductDropdownOpen(false);
            }
            if (unitDropdownRef.current && !unitDropdownRef.current.contains(event.target as Node)) {
                setIsUnitDropdownOpen(false);
            }
        };
        if (isProductDropdownOpen || isUnitDropdownOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isProductDropdownOpen, isUnitDropdownOpen]);

    useEffect(() => {
        if (isOpen) {
            setFormData({
                locationType: 'Shop',
                locationId: shops.length > 0 ? shops[0].id.toString() : '',
                productName: '',
                manufacturer: '',
                category: '',
                status: 'ACTIVE',
                baseUnit: '',
                baseQuantity: '',
                containerQuantity: '',
                containerUnit: '',
                description: '',
                hasBatchNumber: false,
                hasExpiryDate: false,
                imageUrl: '',
                customName: '',
                defaultStockUnit: '',
                reportUnit: '',
                containerPortion: '',
                allowMix: false,
                listingRemarks: '',
                stockUnit: '',
                date: new Date().toISOString().split('T')[0],
                quantity: '',
                unitPrice: '',
                buyingPrice: '',
                batchNumber: '',
                expiryDate: '',
                supplier: 'Unknown',
                invoiceNumber: '',
            });
            setActiveStep(1);
            setPortions([]);
            setSelectedUnits([]);
            setUnitDetails({});
            setErrors({});
            setIsClosing(false);
        }
    }, [isOpen, shops]);

    // Initialize/Sync portions when entering Step 2
    useEffect(() => {
        if (activeStep === 2) {
            setPortions(prevPortions => {
                const newPortions: Portion[] = [];
                const findExisting = (name: string) => prevPortions.find(p => p.name === name);

                // Strictly use selectedUnits if available to prevent unselected container units from appearing
                if (selectedUnits.length > 0) {
                    selectedUnits.forEach((u, idx) => {
                         const existing = findExisting(u);
                         const details = unitDetails[u];
                         // Fallback to form container quantity if detail missing but matches container unit name
                         let qty = details?.quantity || 1;
                         if (!details && u === formData.containerUnit) {
                             qty = formData.containerQuantity ? parseFloat(formData.containerQuantity) : 1;
                         }
                         newPortions.push({ 
                             id: `unit-${idx}`, 
                             name: u, 
                             quantity: qty, 
                             price: existing?.price || 0, 
                             isSelected: existing ? existing.isSelected : true 
                         });
                    });
                } else {
                    // Fallback logic only if no specific units selected (manual entry flow)
                    if (formData.baseUnit) {
                        const existing = findExisting(formData.baseUnit);
                        newPortions.push({ 
                            id: 'base', 
                            name: formData.baseUnit, 
                            quantity: 1, 
                            price: existing?.price || 0, 
                            isSelected: existing ? existing.isSelected : true 
                        });
                    }
                    if (formData.containerUnit && formData.containerUnit !== formData.baseUnit) {
                        const existing = findExisting(formData.containerUnit);
                        const qty = formData.containerQuantity ? parseFloat(formData.containerQuantity) : 1;
                        newPortions.push({ 
                            id: 'container', 
                            name: formData.containerUnit, 
                            quantity: qty, 
                            price: existing?.price || 0, 
                            isSelected: existing ? existing.isSelected : true 
                        });
                    }
                }
                return newPortions;
            });

            setFormData(prev => {
                 const updates: any = {};
                 if (!prev.containerPortion) {
                     updates.containerPortion = selectedUnits.length > 0 ? selectedUnits[0] : (formData.baseUnit || 'Piece');
                 }
                 // Also default report unit if empty
                 if (!prev.reportUnit) {
                     updates.reportUnit = selectedUnits.length > 0 ? selectedUnits[0] : (formData.baseUnit || 'Piece');
                 }
                 // Default defaultStockUnit if empty
                 if (!prev.defaultStockUnit) {
                     updates.defaultStockUnit = selectedUnits.length > 0 ? selectedUnits[0] : (formData.baseUnit || 'Piece');
                 }
                 return { ...prev, ...updates };
            });
        }
    }, [activeStep, formData.baseUnit, formData.containerUnit, formData.containerQuantity, selectedUnits, unitDetails]);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
            setIsClosing(false);
            setErrors({});
        }, 300);
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleStockCalculation = (field: 'quantity' | 'unitPrice' | 'buyingPrice', value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));
        if (errors[field]) {
             setErrors(prev => ({ ...prev, [field]: '' }));
        }
    };

    const handleProductSelect = (product: ProductDefinition) => {
        const units = product.definedUnits?.map(u => u.unitName) || (product.saleUnits ? product.saleUnits.split(',').map(s => s.trim()) : []);
        setSelectedUnits(units);

        const details: Record<string, ProductUnitDefinition> = {};
        if (product.definedUnits) {
            product.definedUnits.forEach(u => details[u.unitName] = u);
        } else {
             units.forEach(u => {
                 details[u] = { unitName: u, quantity: 1, barcode: '' };
             });
        }
        setUnitDetails(details);

        setFormData(prev => ({
            ...prev,
            productName: product.name,
            manufacturer: product.manufacturer,
            category: product.category || '',
            status: product.status || 'ACTIVE',
            baseUnit: product.baseUnit || '',
            baseQuantity: product.baseQuantity?.toString() || '',
            containerQuantity: product.containerQuantity?.toString() || '',
            containerUnit: product.containerUnit || '',
            description: product.remarks || '',
            hasBatchNumber: !!product.hasBatchNumber,
            hasExpiryDate: !!product.hasExpiryDate,
            imageUrl: product.imageUrl || '',
            customName: product.name,
        }));
        setIsProductDropdownOpen(false);
        setProductSearch('');
        setErrors({});
    };

    const handleUnitToggle = (unit: string) => {
        if (selectedUnits.includes(unit)) {
            setSelectedUnits(prev => prev.filter(u => u !== unit));
            const newDetails = { ...unitDetails };
            delete newDetails[unit];
            setUnitDetails(newDetails);
        } else {
            setSelectedUnits(prev => [...prev, unit]);
            setUnitDetails(prev => ({
                ...prev,
                [unit]: { unitName: unit, quantity: 1, barcode: '' }
            }));
        }
    };

    const handleUnitDetailChange = (unit: string, field: keyof ProductUnitDefinition, value: string | number) => {
        setUnitDetails(prev => ({
            ...prev,
            [unit]: {
                ...prev[unit],
                [field]: value
            }
        }));
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
            };
            reader.readAsDataURL(file);
        }
    };

    const validateStep = (step: number) => {
        const newErrors: Record<string, string> = {};
        let isValid = true;

        if (step === 1) {
            if (!formData.productName) newErrors.productName = "Product Name is required";
            if (!formData.manufacturer) newErrors.manufacturer = "Manufacturer is required";
            if (!formData.category) newErrors.category = "Category is required";
            if (!formData.locationId) newErrors.locationId = "Location is required";
            if (!formData.baseUnit) newErrors.baseUnit = "Base Unit is required";
            if (!formData.baseQuantity) newErrors.baseQuantity = "Base Quantity is required";

            if (selectedUnits.length > 0) {
                const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
                if (!unitWithBarcode) {
                    newErrors.units = "At least one selected unit must have a barcode.";
                }
            }
        } else if (step === 2) {
             if (!formData.reportUnit) newErrors.reportUnit = "Reporting unit is required";
             if (!formData.containerPortion) newErrors.containerPortion = "Product unit is required";
             if (!formData.defaultStockUnit) newErrors.defaultStockUnit = "Default stock unit is required";
        } else if (step === 3) {
            if (!formData.stockUnit) newErrors.stockUnit = "Stock unit is required";
            if (!formData.quantity) newErrors.quantity = "Quantity is required";
            if (!formData.buyingPrice) newErrors.buyingPrice = "Buying price is required";
            if (!formData.date) newErrors.date = "Date is required";
        }

        if (Object.keys(newErrors).length > 0) {
            setErrors(newErrors);
            isValid = false;
        } else {
            setErrors({});
        }
        return isValid;
    };

    const clearError = (field: string) => {
        if (errors[field]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[field];
                return newErrors;
            });
        }
    };

    const handleNext = () => {
        if (validateStep(activeStep)) {
            if (activeStep === 2) {
                 // Transfer selected portion price to main unit price if applicable
                 const selectedPortion = portions.find(p => p.name === formData.containerPortion);
                 if (selectedPortion && selectedPortion.price > 0) {
                     setFormData(prev => ({ ...prev, unitPrice: selectedPortion.price.toString() }));
                 }
                 // Auto-fill stock unit in Step 3 based on default setting
                 if (formData.defaultStockUnit) {
                     setFormData(prev => ({ ...prev, stockUnit: formData.defaultStockUnit }));
                 }
            }
            setActiveStep(prev => prev + 1);
        }
    };

    const handleBack = () => {
        setActiveStep(prev => prev - 1);
    };

    const handleSaveFromStep2 = () => {
        if (!validateStep(2)) return;
        onSave({} as StockItem); // Placeholder for unexpected flow
        handleClose();
    };

    const handleSave = () => {
        if (!validateStep(3)) return;

        // PRICE VALIDATION
        const cost = parseFloat(formData.buyingPrice);
        const selling = parseFloat(formData.unitPrice);

        if (!isNaN(cost) && !isNaN(selling) && cost > selling) {
            setPriceError({
                isOpen: true,
                message: `The unit purchasing price (${cost}) is higher than the unit selling price (${selling}) for the unit: ${formData.stockUnit} (Reporting Unit: ${formData.reportUnit}). Please adjust the prices.`
            });
            return;
        }

        let shopName = '';
        let shopId = 0;

        if (formData.locationType === 'Shop') {
            const shop = shops.find(s => s.id === parseInt(formData.locationId));
            if (shop) {
                shopName = shop.name;
                shopId = shop.id;
            }
        } else {
            const warehouse = warehouses.find(w => w.id === parseInt(formData.locationId));
            if (warehouse) {
                shopName = warehouse.name;
                shopId = warehouse.id;
            }
        }

        let mainBarcode = '';
        if (selectedUnits.length > 0) {
             const unitWithBarcode = selectedUnits.find(u => unitDetails[u]?.barcode && unitDetails[u]?.barcode.trim() !== '');
             if (unitWithBarcode) mainBarcode = unitDetails[unitWithBarcode].barcode;
        }

        const newStockItem: StockItem = {
            id: Date.now(),
            productName: formData.productName,
            productSN: `SN-${Date.now()}`, 
            customName: formData.customName || formData.productName,
            barcode: mainBarcode,
            category: formData.category || 'Unknown',
            quantity: parseFloat(formData.quantity),
            unit: formData.stockUnit,
            unitPrice: selling || 0, 
            currency: 'UGX',
            listedBy: 'Current User',
            listedOn: new Date(formData.date).toISOString(),
            shopName: shopName,
            shopId: shopId,
            manufacturer: formData.manufacturer,
            baseUnit: formData.baseUnit || 'Unit',
            hasMultipleSaleUnits: selectedUnits.length > 0,
            reportUnit: formData.reportUnit,
            containerPortion: formData.containerPortion,
            allowMix: formData.allowMix,
            remarks: `${formData.listingRemarks} ${formData.invoiceNumber ? `(Inv: ${formData.invoiceNumber})` : ''}`,
            vatType: 'None', 
            vatPercentage: 0,
        };

        onSave(newStockItem);
        handleClose();
    };

    const filteredProducts = productDefinitions.filter(p => 
        p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
        p.sn.toLowerCase().includes(productSearch.toLowerCase())
    );

    if (!isOpen && !isClosing) return null;

    const StepsHeader = () => (
        <div className={`flex items-center gap-6 px-6 border-b ${theme === 'dark' ? 'border-slate-700' : 'border-slate-200'}`}>
            {['Product details', 'Stock listing Information', 'Stock Information'].map((stepName, index) => {
                const stepNum = index + 1;
                const isActive = activeStep === stepNum;
                const isCompleted = activeStep > stepNum;

                return (
                    <div 
                        key={stepNum}
                        className={`pb-3 pt-4 text-sm font-medium border-b-2 transition-colors flex items-center gap-2 cursor-default ${
                            isActive 
                                ? 'border-yellow-500 text-slate-900 dark:text-slate-100' 
                                : isCompleted 
                                    ? 'border-transparent text-green-600 dark:text-green-400' 
                                    : 'border-transparent text-slate-500 dark:text-slate-400'
                        }`}
                    >
                        <span className={`flex items-center justify-center w-5 h-5 rounded-full text-xs font-bold ${
                            isActive 
                                ? 'bg-yellow-500 text-slate-900' 
                                : isCompleted 
                                    ? 'bg-green-600 text-white' 
                                    : 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400'
                        }`}>
                            {isCompleted ? <Icon name="check-circle" className="w-3 h-3" /> : stepNum}
                        </span>
                        {stepName}
                    </div>
                )
            })}
        </div>
    );

