// ... (Rest of the component: Step2, Step3 components remain unchanged)
const Step2 = ({ data, setData, theme, portions, setPortions, errors, clearError }: { 
    data: any, 
    setData: Function, 
    theme: Theme,
    portions: Portion[],
    setPortions: React.Dispatch<React.SetStateAction<Portion[]>>,
    errors: Record<string, string>,
    clearError: (field: string) => void
}) => {
    const inputClass = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200 placeholder-slate-500' : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400'}`;
    const labelClass = `block text-sm font-medium mb-1 ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`;

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                    <label className={labelClass}>Product</label>
                    <input type="text" value={data.productName} disabled className={`${inputClass} opacity-60 cursor-not-allowed`} />
                </div>
                <ValidatedInput
                    label="Custom Name"
                    name="customName"
                    value={data.customName}
                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => setData({ ...data, customName: e.target.value })}
                    theme={theme}
                />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ValidatedSelect
                    label="Default Stock Unit"
                    name="defaultStockUnit"
                    value={data.defaultStockUnit}
                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => { setData({ ...data, defaultStockUnit: e.target.value }); clearError('defaultStockUnit'); }}
                    error={errors.defaultStockUnit}
                    required
                    theme={theme}
                >
                    <option value="">Select default stock unit</option>
                    {portions.filter(p => p.isSelected).map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                </ValidatedSelect>

                <ValidatedSelect
                    label="Reporting unit"
                    name="reportUnit"
                    value={data.reportUnit}
                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => { setData({ ...data, reportUnit: e.target.value }); clearError('reportUnit'); }}
                    error={errors.reportUnit}
                    required
                    theme={theme}
                >
                    <option value="">Select a reporting unit</option>
                    {portions.filter(p => p.isSelected).map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                </ValidatedSelect>
            </div>

            <div>
                <label className={labelClass}>Product units <span className="text-red-500">*</span></label>
                <div className="flex flex-wrap gap-2 mt-1 mb-3">
                    {portions.map((portion, index) => (
                        <button
                            key={index}
                            type="button"
                            onClick={() => {
                                const newPortions = [...portions];
                                newPortions[index].isSelected = !newPortions[index].isSelected;
                                setPortions(newPortions);
                                clearError('containerPortion'); 
                            }}
                            className={`px-4 py-2 text-sm rounded border transition-colors ${
                                portion.isSelected
                                ? 'bg-yellow-400 text-slate-900 border-yellow-500 font-medium' 
                                : (theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-300 hover:bg-slate-700' : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100')
                            }`}
                        >
                            {portion.name}
                        </button>
                    ))}
                </div>
                {errors.containerPortion && <p className="text-red-500 text-xs mt-1">{errors.containerPortion}</p>}

                <div className="space-y-3">
                    {portions.filter(p => p.isSelected).map((portion, index) => (
                         <div key={portion.id} className={`grid grid-cols-[2fr_1fr_auto] gap-4 items-center p-3 border rounded-md ${theme === 'dark' ? 'bg-slate-800/50 border-slate-700' : 'bg-slate-50 border-slate-200'}`}>
                             <div>
                                 <input type="text" value={portion.name} onChange={(e) => {
                                        const newName = e.target.value;
                                        const newPortions = portions.map(p => p.id === portion.id ? { ...p, name: newName } : p);
                                        setPortions(newPortions);
                                        if (data.containerPortion === portion.name) {
                                             setData({ ...data, containerPortion: newName });
                                        }
                                    }} className={inputClass} placeholder="Portion Name" />
                             </div>
                             <div>
                                 <input type="number" value={portion.price || ''} placeholder="Price" onChange={(e) => {
                                        const newPrice = parseFloat(e.target.value) || 0;
                                        const newPortions = portions.map(p => p.id === portion.id ? { ...p, price: newPrice } : p);
                                        setPortions(newPortions);
                                        if (data.containerPortion === portion.name) {
                                             setData({ ...data, unitPrice: e.target.value });
                                        }
                                    }} className={`${inputClass} text-right`} />
                             </div>
                             <div className="flex items-center justify-center px-2">
                                <input type="radio" name="defaultPortion" checked={data.containerPortion === portion.name} onChange={() => {
                                        setData({ ...data, containerPortion: portion.name, unitPrice: portion.price.toString() });
                                        clearError('containerPortion');
                                    }} className="w-4 h-4 text-yellow-500 bg-gray-100 border-gray-300 focus:ring-yellow-500 dark:focus:ring-yellow-600 dark:ring-offset-gray-800 focus:ring-2 dark:bg-gray-700 dark:border-gray-600 cursor-pointer" />
                             </div>
                        </div>
                    ))}
                </div>
            </div>

            <ValidatedTextArea label="Remarks" name="listingRemarks" value={data.listingRemarks} onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setData({...data, listingRemarks: e.target.value})} theme={theme} rows={3} />
        </div>
    );
};

const Step3 = ({ data, handleInputChange, handleStockCalculation, theme, portions, errors }: any) => {
    const inputClass = `w-full rounded-md border shadow-sm px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-500 ${theme === 'dark' ? 'bg-slate-800 border-slate-600 text-slate-200 placeholder-slate-500' : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400'}`;
    const stockUnitOptions = portions && portions.length > 0 
        ? portions.map((p: any) => <option key={p.name} value={p.name}>{p.name}</option>)
        : availableProductUnits.map(u => <option key={u} value={u}>{u}</option>);

    return (
        <div className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <ValidatedInput label="Invoice Number" name="invoiceNumber" value={data.invoiceNumber} onChange={handleInputChange} placeholder="Optional" theme={theme} />
                <ValidatedSelect label="Stock Unit" name="stockUnit" value={data.stockUnit} onChange={handleInputChange} error={errors.stockUnit} required theme={theme}>
                    <option value="">Select stocking unit</option>
                    {stockUnitOptions}
                </ValidatedSelect>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ValidatedInput label="Qty" name="quantity" value={data.quantity} onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleStockCalculation('quantity', e.target.value)} error={errors.quantity} required type="number" theme={theme} />
                <ValidatedInput label="Purchase price" name="buyingPrice" value={data.buyingPrice} onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleStockCalculation('buyingPrice', e.target.value)} error={errors.buyingPrice} required type="number" theme={theme} />
            </div>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <ValidatedInput label="Unit price" name="unitPrice" value={data.unitPrice} onChange={(e: React.ChangeEvent<HTMLInputElement>) => handleStockCalculation('unitPrice', e.target.value)} type="number" placeholder="0" theme={theme} />
                <ValidatedInput label="Purchase date" name="date" value={data.date} onChange={handleInputChange} error={errors.date} required type="date" theme={theme} />
            </div>
            {(data.hasBatchNumber || data.hasExpiryDate) && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {data.hasBatchNumber && (
