                                    </tr>
                                </thead>
                                <tbody className={`divide-y ${theme === 'dark' ? 'divide-slate-800 bg-slate-900' : 'divide-slate-100 bg-white'}`}>
                                    {filteredShops.length > 0 ? filteredShops.map((shop) => (
                                        <tr key={shop.id} className={theme === 'dark' ? 'hover:bg-slate-800/50' : 'hover:bg-slate-50'}>
                                            <td className={`px-4 py-3 whitespace-nowrap text-sm font-medium ${theme === 'dark' ? 'text-slate-200' : 'text-slate-900'}`}>
                                                {shop.name}
                                                <div className="text-[10px] opacity-60 font-normal">{shop.country}</div>
