import React, { useState } from 'react';
import { Theme } from '../types';
import Icon from './Icon';
import { africaDetailedPaths } from '../data'; // I'll assume we add detailed paths to data.ts

interface CountriesMapPageProps {
    theme: Theme;
}

const CountriesMapPage: React.FC<CountriesMapPageProps> = ({ theme }) => {
    const [hoveredCountry, setHoveredCountry] = useState<string | null>(null);
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

    const handleMouseMove = (e: React.MouseEvent, name: string) => {
        setMousePos({ x: e.clientX, y: e.clientY });
        setHoveredCountry(name);
    };

    const handleMouseLeave = () => {
        setHoveredCountry(null);
    };

    // Colors matching the user's provided screenshot
    const landColor = '#9395e6';
    const hoverColor = '#facc15';
    const borderColor = '#ffffff';
    const bgColor = theme === 'dark' ? 'bg-slate-900' : 'bg-slate-50';

    return (
        <div className={`h-full flex flex-col items-center justify-center p-4 rounded-xl shadow-inner border ${theme === 'dark' ? 'border-slate-700 bg-slate-800/30' : 'border-slate-200 bg-white'}`}>
            <div className="w-full flex justify-between items-center mb-4 px-4">
                <div>
                    <h2 className={`text-xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-800'}`}>Africa Regional Map</h2>
                    <p className={`text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Hover over countries to explore regions</p>
                </div>
                <div className="flex gap-2">
                    <button className="p-2 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 shadow-sm"><Icon name="plus" className="h-4 w-4" /></button>
                    <button className="p-2 rounded border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-700 shadow-sm"><Icon name="x-mark" className="h-4 w-4" /></button>
                </div>
            </div>

            <div className="relative w-full max-w-4xl flex-grow flex items-center justify-center overflow-hidden">
                <svg
                    viewBox="0 0 1000 1000"
                    className="w-full h-full max-h-[80vh] drop-shadow-xl"
                    xmlns="http://www.w3.org/2000/svg"
                >
                    <g>
                        {africaDetailedPaths.map((country) => (
                            <path
                                key={country.id}
                                d={country.d}
                                fill={hoveredCountry === country.name ? hoverColor : landColor}
                                stroke={borderColor}
                                strokeWidth="2"
                                className="transition-all duration-200 cursor-pointer"
                                onMouseMove={(e) => handleMouseMove(e, country.name)}
                                onMouseLeave={handleMouseLeave}
                            />
                        ))}
                    </g>
                </svg>

                {/* Tooltip */}
                {hoveredCountry && (
                    <div 
                        className="fixed pointer-events-none z-[100] px-3 py-1.5 rounded-lg shadow-lg bg-slate-900 text-white text-xs font-bold whitespace-nowrap transform -translate-x-1/2 -translate-y-full mb-4 transition-all duration-75"
                        style={{ left: mousePos.x, top: mousePos.y - 15 }}
                    >
                        {hoveredCountry}
                    </div>
                )}
            </div>

