import React, { useState } from 'react';
import { Theme } from '../types';
import Icon from './Icon';
import { africaDetailedPaths } from '../data';

interface CountriesMapPageProps {
    theme: Theme;
}

const CountriesMapPage: React.FC<CountriesMapPageProps> = ({ theme }) => {
    const [hoveredCountry, setHoveredCountry] = useState<string | null>(null);
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

    const handleMouseMove = (e: React.MouseEvent, name: string) => {
        setMousePos({ x: e.clientX, y: e.clientY });
        setHoveredCountry(name);
    };

    const handleMouseLeave = () => {
        setHoveredCountry(null);
    };

    // Colors matching the user's provided screenshot
    const landColor = '#9395e6';
    const hoverColor = '#facc15';
    const borderColor = '#ffffff';

    return (
        <div className={`h-full flex flex-col items-center justify-center p-0 rounded-xl relative overflow-hidden border ${theme === 'dark' ? 'border-slate-700 bg-slate-900' : 'border-slate-200 bg-[#f5f5f9]'}`}>
            {/* Header Overlay */}
            <div className="absolute top-6 left-8 z-10">
                <h2 className={`text-2xl font-bold ${theme === 'dark' ? 'text-slate-100' : 'text-slate-800'}`}>Africa Regional Map</h2>
                <p className={`text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Hover over countries to explore distribution</p>
            </div>

            {/* Map Container */}
            <div className="relative w-full h-full flex items-center justify-center p-12">
                <svg
                    viewBox="0 0 1000 1000"
                    className="w-full h-full max-h-[85vh] drop-shadow-2xl"
                    xmlns="http://www.w3.org/2000/svg"
                    preserveAspectRatio="xMidYMid meet"
                >
                    <g>
                        {africaDetailedPaths.map((country) => (
                            <path
                                key={country.id}
                                d={country.d}
                                fill={hoveredCountry === country.name ? hoverColor : landColor}
                                stroke={borderColor}
                                strokeWidth="2"
                                className="transition-colors duration-200 cursor-pointer"
                                onMouseMove={(e) => handleMouseMove(e, country.name)}
                                onMouseLeave={handleMouseLeave}
                            />
                        ))}
                    </g>
                </svg>

                {/* Tooltip */}
                {hoveredCountry && (
                    <div 
                        className="fixed pointer-events-none z-[100] px-4 py-2 rounded-lg shadow-xl bg-slate-900 text-white text-sm font-bold whitespace-nowrap transform -translate-x-1/2 -translate-y-full mb-4 transition-all duration-75 border border-slate-700"
                        style={{ left: mousePos.x, top: mousePos.y - 20 }}
                    >
                        {hoveredCountry}
                    </div>
                )}
            </div>

            {/* Control Panel Mockup (Matching the white box in top right of user image) */}
            <div className="absolute top-8 right-8 flex flex-col border border-slate-200 rounded-md overflow-hidden shadow-lg bg-white w-12">
                <button className="h-12 flex items-center justify-center hover:bg-slate-50 text-slate-400 border-b border-slate-100 transition-colors">
                    <div className="w-5 h-0.5 bg-slate-300 rounded-full"></div>
                </button>
                <button className="h-12 flex items-center justify-center hover:bg-slate-50 text-slate-400 transition-colors">
                    <div className="relative w-5 h-5 flex items-center justify-center">
                        <div className="w-5 h-0.5 bg-slate-300 rounded-full absolute"></div>
                        <div className="w-5 h-0.5 bg-slate-300 rounded-full absolute rotate-90"></div>
                    </div>
                </button>
            </div>

            {/* Bottom info banner */}
            <div className={`absolute bottom-6 left-8 p-3 rounded-lg border backdrop-blur-sm ${theme === 'dark' ? 'bg-slate-800/80 border-slate-700 text-slate-300' : 'bg-white/80 border-slate-200 text-slate-600 shadow-sm'}`}>
                <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1.5">
                        <div className="w-3 h-3 rounded-full bg-[#9395e6]"></div>
                        <span className="text-xs font-semibold">Listed Market</span>
                    </div>
                    <div className="flex items-center gap-1.5 ml-4">
                        <div className="w-3 h-3 rounded-full bg-[#facc15]"></div>
                        <span className="text-xs font-semibold">Active Selection</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

